# 제로 트러스트 접근 판정 — 역할(Role)이 있어도 기기 상태가 기준에 못 미치면 막는다
POLICY = {"db-console": {"roles": {"dba", "sre"},
                         "need": {"disk_encrypted", "edr_running", "os_patched"}}}


def decide(user, device, app):
    p = POLICY[app]
    if user["role"] not in p["roles"]:
        return "DENY: 역할 없음"
    missing = p["need"] - {k for k, v in device.items() if v}
    return "DENY: 기기 기준 미달 " + ",".join(sorted(missing)) if missing else "ALLOW"


dev_ok = {"disk_encrypted": True, "edr_running": True, "os_patched": True}
dev_old = {"disk_encrypted": True, "edr_running": True, "os_patched": False}
print(decide({"role": "dba"}, dev_ok, "db-console"))
print(decide({"role": "dba"}, dev_old, "db-console"))
print(decide({"role": "frontend"}, dev_ok, "db-console"))
# --- 실행 결과 ---
# ALLOW
# DENY: 기기 기준 미달 os_patched
# DENY: 역할 없음
